cd /app && node -e "
const fs = require('fs');

// Check orders.ts syntax by parsing it as a rough check
const src = fs.readFileSync('src/lib/orders.ts', 'utf-8');
const test = fs.readFileSync('test/orders.test.ts', 'utf-8');

// Check balanced braces/parens
function checkBalanced(code, label) {
  let parens = 0, braces = 0, brackets = 0;
  let inString = false, strChar = '';
  let inTemplate = false;
  for (let i = 0; i < code.length; i++) {
    const c = code[i];
    const prev = i > 0 ? code[i-1] : '';
    if (inString) {
      if (c === strChar && prev !== '\\\\') inString = false;
      continue;
    }
    if (c === '\"' || c === \"'\" || c === '\`') { inString = true; strChar = c; continue; }
    if (c === '(') parens++;
    else if (c === ')') parens--;
    else if (c === '{') braces++;
    else if (c === '}') braces--;
    else if (c === '[') brackets++;
    else if (c === ']') brackets--;
  }
  console.log(label + ': parens=' + parens + ' braces=' + braces + ' brackets=' + brackets);
  if (parens !== 0 || braces !== 0 || brackets !== 0) {
    console.log('  WARNING: unbalanced!');
  } else {
    console.log('  OK: all balanced');
  }
}

checkBalanced(src, 'src/lib/orders.ts');
checkBalanced(test, 'test/orders.test.ts');

// Verify exports
const hasAddOrder = src.includes('export function addOrder');
const hasGetOrders = src.includes('export function getOrders');
const hasCompleteOrder = src.includes('export function completeOrder');
const hasInterface = src.includes('export interface Order');
console.log('Exports: addOrder=' + hasAddOrder + ' getOrders=' + hasGetOrders + ' completeOrder=' + hasCompleteOrder + ' Order=' + hasInterface);

// Verify test imports match
const testImportsAll = test.includes('addOrder') && test.includes('getOrders') && test.includes('completeOrder');
console.log('Test imports all 3 functions: ' + testImportsAll);

// Check test count
const itCount = (test.match(/\bit\(/g) || []).length;
console.log('Test cases (it blocks): ' + itCount);
"

cd /app && node -e "
const fs = require('fs');
const src = fs.readFileSync('src/lib/orders.ts', 'utf-8');
// Count actual parens outside of strings more carefully
let opens = 0, closes = 0;
for (const line of src.split('\n')) {
  // Skip comment lines
  const trimmed = line.trim();
  if (trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/**')) continue;
  for (const ch of line) {
    if (ch === '(') opens++;
    if (ch === ')') closes++;
  }
}
console.log('Opens:', opens, 'Closes:', closes, 'Diff:', opens - closes);
"
